contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(amount > 0, "amount must be positive");
        require(address(this).balance >= amount, "insufficient test balance");

        uint beforeSender = c.balances(address(this));
        uint beforeContract = address(c).balance;
        uint minDeposit = c.MinDeposit();

        bool reverted;
        try c.Deposit{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterSender = c.balances(address(this));
        uint afterContract = address(c).balance;

        if (!reverted) {
            assert(afterContract == beforeContract + amount);
            if (amount > minDeposit) {
                assert(afterSender == beforeSender + amount);
            } else {
                assert(afterSender == beforeSender);
            }
        } else {
            assert(afterSender == beforeSender);
            assert(afterContract == beforeContract);
        }
    }

    receive() external payable {}
}

